private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }
    int start = strLen - suffLen;
    if (ignoreCase) {
        return str.regionMatches(true, start, suffix, 0, suffLen);
    } else {
        return str.substring(start).equals(suffix);
    }
}

