        int codePoint;
        if ((first & 0x80) == 0) {
            // 1 byte (ASCII)
            codePoint = first;
        } else if ((first & 0xE0) == 0xC0) {
            // 2 bytes
            if (bb.remaining() < 1) throw new IllegalArgumentException("Incomplete 2-byte UTF-8 sequence");
            int second = bb.get() & 0xFF;
            if ((second & 0xC0) != 0x80) throw new IllegalArgumentException("Invalid continuation byte in 2-byte UTF-8");
            codePoint = ((first & 0x1F) << 6) | (second & 0x3F);
        } else if ((first & 0xF0) == 0xE0) {
            // 3 bytes
            if (bb.remaining() < 2) throw new IllegalArgumentException("Incomplete 3-byte UTF-8 sequence");
            int second = bb.get() & 0xFF;
            int third  = bb.get() & 0xFF;
            if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80)
                throw new IllegalArgumentException("Invalid continuation byte in 3-byte UTF-8");
            codePoint = ((first & 0x0F) << 12) | ((second & 0x3F) << 6) | (third & 0x3F);
        } else if ((first & 0xF8) == 0xF0) {
            // 4 bytes
            if (bb.remaining() < 3) throw new IllegalArgumentException("Incomplete 4-byte UTF-8 sequence");
