public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    // Ignore leading '/' for absolute paths
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/', preserving empty segments
    String[] parts = rawPath.split("/", -1);
    for (String part : parts) {
        String segment;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // Fallback to raw part if decoding fails
                segment = part;
            }
        } else {
            segment = part;
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

