public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i == len - 1) {
            throw new Exception("Trailing backslash in string");
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new Exception("Incomplete Unicode escape sequence");
                }
                String hex = str.substring(i + 2, i + 6);
                int codePoint;
