protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end) {
        return ranges;
    }
    long duration = FETCH_DATA_DURATION;
    if (duration <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    long current = start;
    while (current < end) {
        long next = current + duration;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

