static long compressTimeBucket(long timeBucket,int dayStep){ 
    if(dayStep <= 0) throw new IllegalArgumentException("dayStep must be positive"); 
    int year = (int)(timeBucket / 10000); 
    int month = (int)((timeBucket / 100) % 100); 
    int day = (int)(timeBucket % 100); 
    try{ 
        java.time.LocalDate.of(year, month, day); 
    }catch(IllegalArgumentException | java.time.DateTimeException e){ 
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket); 
    } 
    int startDay = ((day - 1) / dayStep) * dayStep + 1; 
    long compressed = ((long)year) * 10000 + ((long)month) * 100 + startDay; 
    return compressed; 
}

