public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Increase by 2 to stay odd
        // Avoid overflow: if candidate is close to Integer.MAX_VALUE, return Integer.MAX_VALUE
        if (candidate >= Integer.MAX_VALUE - 2) {
            return Integer.MAX_VALUE;
        }
        candidate += 2;
    }

    /* Helper method to test primality */
    static boolean isPrime(int n){
        if (n <= 3) {
            return n > 1;
        }
        if ((n & 1) == 0) {
            return false;
        }
        int sqrt = (int)Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

